static void append(World*w,const char*file){FILE*f=records(file);Agent a;while(read_record(f,&a,sizeof a)){unsigned s=0;while(s<CAP&&w->agents[s].alive)s++;if(s==CAP)fail("capacity exceeded");a.id=w->next_id++;a.parent=0;a.lineage=++w->founders;a.born=w->tick;a.last_mail=a.last_reward=a.last_request=0;w->agents[s]=a;w->population++;}fclose(f);validate(w);}
int main(int argc,char**argv){if(argc<3)fail("init DIR RAW SEED CONTEXT | step DIR N | inspect DIR | inject DIR RAW");directory=argv[2];World*w;
if(!strcmp(argv[1],"init")){if(argc<6)fail("args");refuse_existing(directory);mkdir(directory,0700);char p[4096];bridge_path(p,directory,"mail");mkdir(p,0700);bridge_path(p,directory,"bridge");mkdir(p,0700);FILE*f=records(argv[5]);Header h;w=calloc(1,sizeof(*w));if(fread(&h,sizeof h,1,f)!=1||h.magic!=MAGIC||h.size!=sizeof(*w)||fread(w,sizeof(*w),1,f)!=1||h.checksum!=hash(w,sizeof(*w)))fail("context");fclose(f);memset(w->agents,0,sizeof(w->agents));w->tick=0;w->rng=strtoull(argv[4],NULL,10);w->next_id=1;w->population=w->founders=w->custodians=0;w->births=w->deaths=w->mutations=w->mail_seq=w->mail_bytes=0;w->restores=w->perfect=w->awarded=w->mail_rejected=w->requests=w->request_rejected=w->library_reads=w->library_imports=w->shared_writes=w->code_writes=w->ram_writes=w->keeper_perfect=w->descendant_perfect=w->energy_reward=w->work=w->last_dispatch=0;memset(w->shared_owner,0,sizeof w->shared_owner);append(w,argv[3]);save(w);}
else{w=load();if(!strcmp(argv[1],"step")){if(argc<4)fail("args");recover_mail(w);native_eat_gain=parameter(directory,"native_eat_gain",6,1,64);native_mutation_divisor=parameter(directory,"native_mutation_divisor",4,1,100000);native_max_age=parameter(directory,"native_max_age",16384,256,1000000);unsigned char b[RAM];size_t z=stimulus(directory,b,sizeof b);if(z)memcpy(w->shared[7],b,z);begin_emit(directory);for(unsigned n=number(argv[3]);n&&w->population;n--)tick(w);end_emit();save(w);}else if(!strcmp(argv[1],"inject")){if(argc<4)fail("args");append(w,argv[3]);save(w);}else if(!strcmp(argv[1],"export")){if(argc<4)fail("args");FILE*f=fopen(argv[3],"wb");if(!f)fail("export open");for(unsigned i=0;i<CAP;i++)if(w->agents[i].alive&&fwrite(&w->agents[i],sizeof(Agent),1,f)!=1)fail("export write");durable(f);}else if(strcmp(argv[1],"inspect"))fail("command");}inspect(w);free(w);return 0;}
